---MIG
-- 001_init — the three tables and the indexes of docs/spec.md §1,
-- plus article_enrichments.attempts (docs/deviations.md row 7) and
-- articles.headline_text (row 15).

CREATE TABLE articles (
  id            bigserial PRIMARY KEY,
  external_id   int UNIQUE,                -- the brief's id
  headline      text,                      -- raw, as received; may be '' (article 17)
  headline_text text NOT NULL,             -- HTML stripped, like body_text. Postgres indexes the
                                           -- words inside a tag (img, onerror, …), so the raw
                                           -- headline must not reach to_tsvector
  body          text NOT NULL,             -- raw, unsanitised; the source is evidence
  body_text     text NOT NULL,             -- HTML stripped; used for search and the LLM.
                                           -- NOT NULL: a null here would make tsv null and
                                           -- the article silently unsearchable
  source        text NOT NULL,
  language      text NOT NULL,             -- 'en' | 'ar' | 'zh' | …
  published_at  timestamptz NOT NULL,
  content_hash  bytea NOT NULL,            -- sha256(normalised headline_text + body_text)
  -- The config is a constant in each branch: a config chosen by an expression is
  -- not immutable and a generated column rejects it.
  tsv           tsvector GENERATED ALWAYS AS (
                  CASE WHEN language = 'en'
                    THEN to_tsvector('english', headline_text || ' ' || body_text)
                    ELSE to_tsvector('simple',  headline_text || ' ' || body_text)
                  END) STORED
);

-- One row per article per run key (requested_model, prompt_version, taxonomy_version):
-- two models over the same articles are two sets of rows.
CREATE TABLE article_enrichments (
  article_id        bigint REFERENCES articles (id),
  requested_model   text,                  -- 'mock', or the model id asked for
  prompt_version    text,
  taxonomy_version  text,
  content_hash      bytea,                 -- the article's hash when this row was produced
  status            text CHECK (status IN ('pending', 'processing', 'done', 'failed')),
  claimed_at        timestamptz,
  summary           text,
  sentiment         text CHECK (sentiment IN ('positive', 'negative', 'neutral', 'mixed')),
  tags              text[],                -- 1..3 ids from the taxonomy
  model             text,                  -- as reported in the provider response
  provider          text,                  -- as reported in the provider response
  input_tokens      int,
  output_tokens     int,
  latency_ms        int,
  cost_usd          numeric(10, 6),
  attempts          int,                   -- provider calls made: 1, or 2 after the retry; null while pending
  error             text,
  updated_at        timestamptz,
  PRIMARY KEY (article_id, requested_model, prompt_version, taxonomy_version)
);

CREATE TABLE enrichment_budget (
  day          date PRIMARY KEY,           -- UTC
  tokens_used  bigint NOT NULL DEFAULT 0
);

-- Keyset pagination: the list's ORDER BY, with id as the tiebreak.
CREATE INDEX articles_published_idx
  ON articles (published_at DESC, id DESC);

-- Source filter: equality column first, then the keyset order and its tiebreak.
CREATE INDEX articles_source_published_idx
  ON articles (source, published_at DESC, id DESC);

-- Language filter: same shape as the source index.
CREATE INDEX articles_language_published_idx
  ON articles (language, published_at DESC, id DESC);

-- Boolean search: every leaf is `tsv @@ <tsquery>`.
CREATE INDEX articles_tsv_idx
  ON articles USING gin (tsv);

-- Topic filter: `tags @> ARRAY[topic]`.
CREATE INDEX article_enrichments_tags_idx
  ON article_enrichments USING gin (tags);

-- Dedup lookup before a provider call; partial, because only finished rows can be copied.
CREATE INDEX article_enrichments_dedup_idx
  ON article_enrichments (content_hash, requested_model, prompt_version, taxonomy_version)
  WHERE status = 'done';
---DB
// The one place the app's connection pool is created. Query functions under lib/
// take a `Queryable` argument instead of importing the pool, so tests pass the
// media_test database and the scale scripts pass the synthetic one.
import { Pool, type QueryResult, type QueryResultRow } from "pg";

export interface Queryable {
  query<R extends QueryResultRow = QueryResultRow>(
    text: string,
    values?: unknown[],
  ): Promise<QueryResult<R>>;
}

let pool: Pool | undefined;

export function getPool(): Pool {
  if (!pool) {
    const url = process.env.DATABASE_URL;
    if (!url) throw new Error("DATABASE_URL is not set");
    pool = new Pool({ connectionString: url });
  }
  return pool;
}
---STRIP
// Produces `body_text` from an article body: the text that search indexes and the
// LLM reads. The raw body is stored next to it, unchanged.
//
// This is not a sanitizer and its output is not safe to render as HTML: decoded
// entities can spell a tag again. Everything is rendered as React text nodes.

const NAMED: Record<string, string> = {
  amp: "&",
  lt: "<",
  gt: ">",
  quot: '"',
  apos: "'",
  nbsp: " ",
};

function decodeEntity(match: string, body: string): string {
  if (body[0] !== "#") return NAMED[body.toLowerCase()] ?? match;
  const hex = body[1] === "x" || body[1] === "X";
  const code = parseInt(body.slice(hex ? 2 : 1), hex ? 16 : 10);
  return Number.isInteger(code) && code > 0 && code <= 0x10ffff
    ? String.fromCodePoint(code)
    : match;
}

export function stripHtml(html: string): string {
  return (
    html
      .replace(/<!--[\s\S]*?-->/g, " ")
      // script and style go with their contents: code is not article text
      .replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1\s*>/gi, " ")
      // a tag starts with a letter, so "3 < 5" is left alone. Replaced by a space,
      // not nothing: "<p>a</p><p>b</p>" must not become one word
      .replace(/<\/?[a-zA-Z][^>]*>/g, " ")
      .replace(/&(#[xX]?[0-9a-fA-F]+|[a-zA-Z]+);/g, decodeEntity)
      .replace(/\s+/g, " ")
      .trim()
  );
}
---SEED
// npm run seed — loads docs/sample_articles.json into `articles`.
// Idempotent: a re-run inserts 0 rows (spec S1); an existing external_id is left as it is.
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { Client } from "pg";
import type { Queryable } from "../lib/db";
import { stripHtml } from "../lib/html/strip";

const SAMPLE_FILE = fileURLToPath(
  new URL("../docs/sample_articles.json", import.meta.url),
);

export type SourceArticle = {
  id: number;
  headline: string;
  body: string;
  source: string;
  published_at: string;
  language: string;
};

export type ArticleRow = {
  externalId: number;
  headline: string;
  headlineText: string;
  body: string;
  bodyText: string;
  source: string;
  language: string;
  publishedAt: string;
  contentHash: Buffer;
};

const STRING_FIELDS = [
  "headline",
  "body",
  "source",
  "published_at",
  "language",
] as const;

/** A type guard for the source file, which is input like any other. */
export function parseArticles(data: unknown): SourceArticle[] {
  if (!Array.isArray(data)) throw new Error("articles: expected an array");
  return data.map((item: unknown, index) => {
    const record = (item ?? {}) as Record<string, unknown>;
    if (!Number.isInteger(record.id)) {
      throw new Error(`articles[${index}]: id must be an integer`);
    }
    for (const field of STRING_FIELDS) {
      if (typeof record[field] !== "string") {
        throw new Error(`articles[${index}]: ${field} must be a string`);
      }
    }
    if (Number.isNaN(Date.parse(record.published_at as string))) {
      throw new Error(`articles[${index}]: published_at is not a date`);
    }
    return record as SourceArticle;
  });
}

export function loadSampleArticles(): SourceArticle[] {
  return parseArticles(JSON.parse(readFileSync(SAMPLE_FILE, "utf8")));
}

const normalise = (text: string): string =>
  text.normalize("NFC").replace(/\s+/g, " ").trim();

/**
 * sha256 over the normalised stripped headline and body text. Normalised = NFC, whitespace
 * runs collapsed, trimmed; case is kept. The newline cannot occur inside either
 * part after normalisation, so it marks where the headline ends.
 */
export function contentHash(headlineText: string, bodyText: string): Buffer {
  return createHash("sha256")
    .update(normalise(headlineText) + "\n" + normalise(bodyText), "utf8")
    .digest();
}

export function toRow(article: SourceArticle): ArticleRow {
  const headlineText = stripHtml(article.headline);
  const bodyText = stripHtml(article.body);
  return {
    externalId: article.id,
    headline: article.headline, // raw, '' included (article 17)
    headlineText,
    body: article.body,
    bodyText,
    source: article.source,
    language: article.language,
    publishedAt: article.published_at,
    contentHash: contentHash(headlineText, bodyText),
  };
}

/** Inserts the articles that are not there yet, in one statement; returns how many. */
export async function seed(
  db: Queryable,
  articles: SourceArticle[],
): Promise<number> {
  const rows = articles.map(toRow);
  const result = await db.query(
    `INSERT INTO articles
       (external_id, headline, headline_text, body, body_text, source, language, published_at, content_hash)
     SELECT * FROM unnest(
       $1::int[], $2::text[], $3::text[], $4::text[], $5::text[],
       $6::text[], $7::text[], $8::timestamptz[], $9::bytea[])
     ON CONFLICT (external_id) DO NOTHING`,
    [
      rows.map((r) => r.externalId),
      rows.map((r) => r.headline),
      rows.map((r) => r.headlineText),
      rows.map((r) => r.body),
      rows.map((r) => r.bodyText),
      rows.map((r) => r.source),
      rows.map((r) => r.language),
      rows.map((r) => r.publishedAt),
      rows.map((r) => r.contentHash),
    ],
  );
  return result.rowCount ?? 0;
}

async function main(): Promise<void> {
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error("DATABASE_URL is not set");
  const articles = loadSampleArticles();
  const client = new Client({ connectionString: url });
  await client.connect();
  try {
    const inserted = await seed(client, articles);
    console.log(`seed: inserted ${inserted} of ${articles.length} articles`);
  } finally {
    await client.end();
  }
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main().catch((error) => {
    console.error(error);
    process.exit(1);
  });
}
---MIGRATE
// npm run migrate — applies db/migrations/*.sql in name order, once each.
// Idempotent: applied files are recorded in schema_migrations and skipped.
import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { Client } from "pg";

const MIGRATIONS_DIR = fileURLToPath(
  new URL("../db/migrations", import.meta.url),
);
// Any constant: two `init` containers starting together must not both apply a file.
const LOCK_KEY = 7462001;

/** Applies the pending migrations and returns their file names. */
export async function migrate(client: Client): Promise<string[]> {
  const files = readdirSync(MIGRATIONS_DIR)
    .filter((name) => name.endsWith(".sql"))
    .sort();
  const applied: string[] = [];

  await client.query("SELECT pg_advisory_lock($1)", [LOCK_KEY]);
  try {
    await client.query(
      "CREATE TABLE IF NOT EXISTS schema_migrations (name text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now())",
    );
    const { rows } = await client.query<{ name: string }>(
      "SELECT name FROM schema_migrations",
    );
    const done = new Set(rows.map((row) => row.name));

    for (const name of files) {
      if (done.has(name)) continue;
      // The file is a constant from the repo, sent as-is; it takes no parameters.
      const sql = readFileSync(join(MIGRATIONS_DIR, name), "utf8");
      await client.query("BEGIN");
      try {
        await client.query(sql);
        await client.query("INSERT INTO schema_migrations (name) VALUES ($1)", [
          name,
        ]);
        await client.query("COMMIT");
      } catch (error) {
        await client.query("ROLLBACK");
        throw error;
      }
      applied.push(name);
    }
  } finally {
    await client.query("SELECT pg_advisory_unlock($1)", [LOCK_KEY]);
  }
  return applied;
}

async function main(): Promise<void> {
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error("DATABASE_URL is not set");
  const client = new Client({ connectionString: url });
  await client.connect();
  try {
    const applied = await migrate(client);
    console.log(
      applied.length === 0
        ? "migrate: nothing to apply"
        : "migrate: applied " + applied.join(", "),
    );
  } finally {
    await client.end();
  }
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main().catch((error) => {
    console.error(error);
    process.exit(1);
  });
}

