// The provider contract (spec §3), and the one place the environment decides the
// mode and the run key.
import { MockProvider } from "./mock";
import { OpenAICompatibleProvider } from "./openai-compatible";
import { PROMPT_VERSION, type ProviderInput } from "./prompt";
import { TAXONOMY_VERSION } from "./taxonomy";

export type ProviderResult = {
  raw: unknown;
  /** As reported in the response; "" when the response does not say. */
  model: string;
  provider: string;
  inputTokens?: number;
  outputTokens?: number;
  costUsd?: number;
};

export interface EnrichmentProvider {
  enrich(
    input: ProviderInput,
    opts: { signal: AbortSignal },
  ): Promise<ProviderResult>;
}

/**
 * A failed provider call. `status` is the HTTP status, or undefined when no
 * response arrived. The message never carries response text.
 */
export class ProviderError extends Error {
  constructor(readonly status: number | undefined) {
    super(status === undefined ? "no response" : `HTTP ${status}`);
    this.name = "ProviderError";
  }
}

export type RunKey = {
  requestedModel: string;
  promptVersion: string;
  taxonomyVersion: string;
};

type Env = Record<string, string | undefined>;

const OPENROUTER_BASE_URL = "https://openrouter.ai/api/v1";

const runKey = (requestedModel: string): RunKey => ({
  requestedModel,
  promptVersion: PROMPT_VERSION,
  taxonomyVersion: TAXONOMY_VERSION,
});

export function llmMode(env: Env = process.env): "mock" | "live" {
  const mode = env.LLM_MODE || "mock";
  if (mode !== "mock" && mode !== "live") {
    throw new Error(`LLM_MODE must be "mock" or "live", not "${mode}"`);
  }
  return mode;
}

/** The run key of the worker, the API and the UI: mock → 'mock', live → ENRICH_MODEL. */
export function activeRunKey(env: Env = process.env): RunKey {
  if (llmMode(env) === "mock") return runKey("mock");
  if (!env.ENRICH_MODEL) {
    throw new Error("LLM_MODE=live needs ENRICH_MODEL");
  }
  return runKey(env.ENRICH_MODEL);
}

/**
 * The run key of the read-only scripts (score, metrics): ENRICH_MODEL if set,
 * otherwise mock. They do not read LLM_MODE and need no key (deviation 8).
 */
export function readOnlyRunKey(env: Env = process.env): RunKey {
  return runKey(env.ENRICH_MODEL || "mock");
}

/** Live mode fails here, at startup, without a key and a model. */
export function createProvider(env: Env = process.env): EnrichmentProvider {
  if (llmMode(env) === "mock") return new MockProvider();
  if (!env.OPENROUTER_API_KEY || !env.ENRICH_MODEL) {
    throw new Error(
      "LLM_MODE=live needs OPENROUTER_API_KEY and ENRICH_MODEL in the environment",
    );
  }
  return new OpenAICompatibleProvider(
    OPENROUTER_BASE_URL,
    env.ENRICH_MODEL,
    env.OPENROUTER_API_KEY,
  );
}

// The live provider: one chat-completions request per article to an
// OpenAI-compatible endpoint (OpenRouter). The model gets the two messages and the
// output schema and nothing else: no callable capabilities are declared, and
// nothing it returns is fetched or followed.
//
// Model, provider, tokens and cost are read from the response (spec S9). Every one
// of them is optional here: a field the response does not carry is stored as null,
// never computed from the request.
import {
  ProviderError,
  type EnrichmentProvider,
  type ProviderResult,
} from "./provider";
import {
  buildMessages,
  OUTPUT_CAP_TOKENS,
  type ProviderInput,
} from "./prompt";
import { RESPONSE_JSON_SCHEMA } from "./schema";

const num = (value: unknown): number | undefined =>
  typeof value === "number" && Number.isFinite(value) ? value : undefined;
const str = (value: unknown): string =>
  typeof value === "string" ? value : "";

export class OpenAICompatibleProvider implements EnrichmentProvider {
  constructor(
    private readonly baseUrl: string,
    private readonly model: string,
    private readonly apiKey: string,
  ) {}

  requestBody(input: ProviderInput): Record<string, unknown> {
    const { system, user } = buildMessages(input);
    return {
      model: this.model,
      messages: [
        { role: "system", content: system },
        { role: "user", content: user },
      ],
      response_format: {
        type: "json_schema",
        json_schema: {
          name: "enrichment",
          strict: true,
          schema: RESPONSE_JSON_SCHEMA,
        },
      },
      max_tokens: OUTPUT_CAP_TOKENS,
      // OpenRouter: report cost in `usage`, and route only to an upstream that
      // honours every parameter above, response_format included.
      usage: { include: true },
      provider: { require_parameters: true },
    };
  }

  async enrich(
    input: ProviderInput,
    opts: { signal: AbortSignal },
  ): Promise<ProviderResult> {
    let response: Response;
    try {
      response = await fetch(`${this.baseUrl}/chat/completions`, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${this.apiKey}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(this.requestBody(input)),
        signal: opts.signal,
      });
    } catch (error) {
      if (opts.signal.aborted) throw error; // the caller's timeout
      throw new ProviderError(undefined);
    }
    if (!response.ok) throw new ProviderError(response.status);

    let data: Record<string, unknown>;
    try {
      data = (await response.json()) as Record<string, unknown>;
    } catch (error) {
      if (opts.signal.aborted) throw error;
      throw new ProviderError(undefined);
    }
    // OpenRouter can answer 200 with an error object in the body.
    const failure = data.error as { code?: unknown } | undefined;
    if (failure) throw new ProviderError(num(failure.code) ?? 502);

    const usage = (data.usage ?? {}) as Record<string, unknown>;
    const choices = data.choices as
      { message?: { content?: unknown } }[] | undefined;
    return {
      raw: choices?.[0]?.message?.content ?? null,
      model: str(data.model),
      provider: str(data.provider),
      inputTokens: num(usage.prompt_tokens),
      outputTokens: num(usage.completion_tokens),
      costUsd: num(usage.cost),
    };
  }
}

