      summary: "A summary copied from an earlier duplicate.",
      sentiment: "mixed",
      tags: ["other"],
      model: "m",
      provider: "p",
      input_tokens: null,
      output_tokens: null,
      latency_ms: null,
      cost_usd: null,
      attempts: null,
      status: "done",
    });
  });
});

