// npm run eval:metrics — runs scripts/enrichment-metrics.sql for one run key and
// prints the key first. The model is ENRICH_MODEL if set, otherwise mock; LLM_MODE
// is not read and no key is needed (deviation 8).
import { readFileSync } from "node:fs";
import { getPool } from "../lib/db";
import { readOnlyRunKey } from "../lib/enrich/provider";

async function main(): Promise<void> {
  const key = readOnlyRunKey();
  const params = [key.requestedModel, key.promptVersion, key.taxonomyVersion];
  console.log(`run key: ${params.join(" / ")}`);
  // The file is a constant from the repo; the run key goes in as parameters.
  const sql = readFileSync(
    new URL("./enrichment-metrics.sql", import.meta.url),
    "utf8",
  );
  const pool = getPool();
  try {
    const { rows } = await pool.query(sql, params);
    for (const [name, value] of Object.entries(rows[0] ?? {})) {
      console.log(`${name}: ${value === null ? "null" : String(value)}`);
    }
  } finally {
    await pool.end();
  }
}

main().catch((error) => {
  console.error(error instanceof Error ? error.message : error);
  process.exit(1);
});

// npm run score — compares one run key's rows with tests/golden.json (spec §7).
// The model is ENRICH_MODEL if set, otherwise mock; LLM_MODE is not read.
import { readFileSync } from "node:fs";
import { getPool } from "../lib/db";
import { readOnlyRunKey } from "../lib/enrich/provider";
import { SENTIMENTS, TAXONOMY } from "../lib/enrich/taxonomy";

type Label = { external_id: number; sentiment: string; acceptable_tags: string[] };
type Row = { external_id: number; status: string; sentiment: string | null; tags: string[] | null };

async function main(): Promise<number> {
  const key = readOnlyRunKey();
  const params = [key.requestedModel, key.promptVersion, key.taxonomyVersion];
  console.log(`run key: ${params.join(" / ")}`);

  const file = new URL("../tests/golden.json", import.meta.url);
  const { labels } = JSON.parse(readFileSync(file, "utf8")) as { labels: Label[] };
  const unlabelled = labels.filter(
    (l) =>
      !(SENTIMENTS as readonly string[]).includes(l.sentiment) ||
      l.acceptable_tags.length === 0 ||
      l.acceptable_tags.some((t) => !(TAXONOMY as readonly string[]).includes(t)),
  );
  if (unlabelled.length > 0) {
    console.error(
      `score: tests/golden.json is not fully labelled: ${unlabelled.length} of ${labels.length} entries are empty or outside the enums`,
    );
    return 1;
  }

  const pool = getPool();
  const { rows } = await pool
    .query<Row>(
      `SELECT a.external_id, e.status, e.sentiment, e.tags
         FROM article_enrichments e JOIN articles a ON a.id = e.article_id
        WHERE e.requested_model = $1 AND e.prompt_version = $2 AND e.taxonomy_version = $3`,
      params,
    )
    .finally(() => pool.end());
  const byId = new Map(rows.map((r) => [r.external_id, r]));

  let sentiment = 0;
  let tags = 0;
  for (const label of labels) {
    const row = byId.get(label.external_id);
    const done = row?.status === "done";
    const sentimentOk = done && row.sentiment === label.sentiment;
    const tagsOk = done && (row.tags ?? []).every((t) => label.acceptable_tags.includes(t));
    if (sentimentOk) sentiment++;
    if (tagsOk) tags++;
    if (!sentimentOk || !tagsOk) {
      console.log(
        `article ${label.external_id}: ${row?.status ?? "no row"}; sentiment ${row?.sentiment ?? "null"} (golden ${label.sentiment}); tags [${row?.tags ?? ""}] (acceptable [${label.acceptable_tags}])`,
      );
    }
  }
  console.log(`sentiment agreement: ${sentiment} / ${labels.length} (a row that is not done counts as a miss)`);
  console.log(
    `tag validity: ${tags} / ${labels.length} (valid = the row is done and every tag it has is in the article's acceptable_tags)`,
  );
  return 0;
}

main().then(
  (code) => process.exit(code),
  (error) => {
    console.error(error instanceof Error ? error.message : error);
    process.exit(1);
  },
);

// npm run eval:export [-- --mock-fixtures] — writes the article_enrichments rows
// of ENRICH_MODEL to docs/evaluations/enrichments-<model>.json, as they are (spec
// S11). It reads the database only and calls no provider.
//
// With --mock-fixtures it also rewrites tests/fixtures/mock-enrichments.json from
// the same rows, token counts included, so the mock replays that model's run.
import { mkdirSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { getPool } from "../lib/db";
import {
  inputKey,
  MOCK_FIXTURES_URL,
  type MockFixtureFile,
} from "../lib/enrich/mock";
import { readOnlyRunKey } from "../lib/enrich/provider";
import { toProviderInput } from "../lib/enrich/prompt";

export const EVALUATIONS_DIR = fileURLToPath(
  new URL("../docs/evaluations/", import.meta.url),
);

/** A model id as a file name: `/` and anything else outside [A-Za-z0-9._-] → `-`. */
export const fileSafe = (model: string): string =>
  model.replace(/[^A-Za-z0-9._-]/g, "-");

type Row = {
  external_id: number;
  headline: string;
  body: string;
  language: string;
  status: string;
  summary: string | null;
  sentiment: string | null;
  tags: string[] | null;
  model: string | null;
  provider: string | null;
  input_tokens: number | null;
  output_tokens: number | null;
  latency_ms: number | null;
  cost_usd: string | null;
  attempts: number | null;
  error: string | null;
  updated_at: Date;
};

async function main(): Promise<number> {
  if (!process.env.ENRICH_MODEL) {
    console.error("eval:export: set ENRICH_MODEL to the model id to export");
    return 1;
  }
  const key = readOnlyRunKey();
  const pool = getPool();
  const { rows } = await pool
    .query<Row>(
      `SELECT a.external_id, a.headline, a.body, a.language,
              e.status, e.summary, e.sentiment, e.tags, e.model, e.provider,
              e.input_tokens, e.output_tokens, e.latency_ms, e.cost_usd,
              e.attempts, e.error, e.updated_at
         FROM article_enrichments e JOIN articles a ON a.id = e.article_id
        WHERE e.requested_model = $1 AND e.prompt_version = $2 AND e.taxonomy_version = $3
        ORDER BY a.external_id`,
      [key.requestedModel, key.promptVersion, key.taxonomyVersion],
    )
    .finally(() => pool.end());
  if (rows.length === 0) {
    console.error(`eval:export: no rows for ${key.requestedModel}`);
    return 1;
  }

  mkdirSync(EVALUATIONS_DIR, { recursive: true });
  const target = `${EVALUATIONS_DIR}enrichments-${fileSafe(key.requestedModel)}.json`;
  const snapshot = {
    run_key: key,
    exported_at: new Date().toISOString(),
    rows: rows.map(({ headline: _h, body: _b, language: _l, ...row }) => row),
  };
  writeFileSync(target, JSON.stringify(snapshot, null, 2) + "\n");
  console.log(`eval:export: ${rows.length} rows → ${target}`);

  if (process.argv.includes("--mock-fixtures")) {
    const notDone = rows.filter((r) => r.status !== "done");
    if (notDone.length > 0) {
      // The mock can replay an output, not a failure: a human decides what the
      // default path shows for these articles.
      console.error(
        `eval:export: mock fixtures not written: ${notDone.length} row(s) are not done (articles ${notDone.map((r) => r.external_id).join(", ")})`,
      );
      return 1;
    }
    const last = rows.reduce((a, b) => (a.updated_at > b.updated_at ? a : b));
    const file: MockFixtureFile = {
      provenance: "live",
      model: key.requestedModel,
      run_date: last.updated_at.toISOString().slice(0, 10),
      note: "Recorded output of the live run named above, exported by `npm run eval:export -- --mock-fixtures`; token counts are the provider-reported ones (summed when a row took a retry). `key` is the hash of the provider input (lib/enrich/mock.ts).",
      fixtures: rows.map((r) => ({
        external_id: r.external_id,
        key: inputKey(toProviderInput(r)),
        output: { summary: r.summary, sentiment: r.sentiment, tags: r.tags },
        input_tokens: r.input_tokens ?? 0,
        output_tokens: r.output_tokens ?? 0,
      })),
    };
    writeFileSync(MOCK_FIXTURES_URL, JSON.stringify(file, null, 2) + "\n");
    console.log(`eval:export: mock fixtures ← ${key.requestedModel}`);
  }
  return 0;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main().then(
    (code) => process.exit(code),
    (error) => {
      console.error(error instanceof Error ? error.message : error);
      process.exit(1);
    },
  );
}

