  const provider = createProvider(env); // throws without a key and a model
  const model = env.ENRICH_MODEL as string;
  const target = `${EVALUATIONS_DIR}adversarial-${fileSafe(model)}.json`;
  if (existsSync(target)) {
    console.error(
